50	/**
51	 * This class coordinates reading and writing Container checksum information for all containers.
52	 */
53	public class ContainerChecksumTreeManager {
54	
55	  private static final Logger LOG = LoggerFactory.getLogger(ContainerChecksumTreeManager.class);
56	
57	  // Used to coordinate writes to each container's checksum file.
58	  // Each container ID is mapped to a stripe.
59	  // The file is atomically renamed into place, so readers do not need coordination.
60	  private final Striped<Lock> fileLock;
61	  private final ContainerMerkleTreeMetrics metrics;
62	
63	  /**
64	   * Creates one instance that should be used to coordinate all container checksum info within a datanode.
65	   */
66	  public ContainerChecksumTreeManager(ConfigurationSource conf) {
67	    fileLock = SimpleStriped.custom(conf.getObject(DatanodeConfiguration.class).getContainerChecksumLockStripes(),
68	        () -> new ReentrantLock(true));
69	    metrics = ContainerMerkleTreeMetrics.create();
70	  }
71	
72	  public void stop() {
73	    ContainerMerkleTreeMetrics.unregister();
74	  }
