150	  /**
151	   * Compares this container replica's checksum tree against a peer's checksum tree and returns a report detailing
152	   * the data our replica is missing or has corrupted. Callers can act on this report to repair their container
153	   * replica using the peer's replica. The diff is computed from the local perspective, so differences where the
154	   * peer's tree is missing data are excluded. Blocks marked as deleted in either checksum info are also excluded.
155	   *
156	   * @param thisContainer The container data for our local replica.
157	   * @param peerChecksumInfo The checksum info of the peer's replica to compare against.
158	   * @return A {@link ContainerDiffReport} summarizing what our replica needs to repair from the peer.
159	   */
160	  public ContainerDiffReport diff(KeyValueContainerData thisContainer,
161	      ContainerProtos.ContainerChecksumInfo peerChecksumInfo) throws StorageContainerException {
162	    ContainerDiffReport report = new ContainerDiffReport();
163	    long containerID = thisContainer.getContainerID();
164	    try {
165	      captureLatencyNs(metrics.getMerkleTreeDiffLatencyNS(), () -> {
166	        if (!getContainerChecksumFile(thisContainer).exists()) {
167	          throw new StorageContainerException("Container checksum file not found for container " + containerID,
168	              ContainerProtos.Result.IO_EXCEPTION);
169	        }
170	
171	        Optional<ContainerProtos.ContainerChecksumInfo.Builder> thisChecksumInfo = read(thisContainer);
172	        if (!thisChecksumInfo.isPresent()) {
173	          throw new StorageContainerException("Container checksum file not found for container " + containerID,
174	              ContainerProtos.Result.IO_EXCEPTION);
175	        }
176	
177	        if (containerID != peerChecksumInfo.getContainerID()) {
178	          throw new StorageContainerException("Container ID does not match. Local container ID "
179	              + containerID + " , Peer container ID " + peerChecksumInfo.getContainerID(),
180	              ContainerProtos.Result.CONTAINER_ID_MISMATCH);
181	        }
182	
183	        compareContainerMerkleTree(thisChecksumInfo.get().build(), peerChecksumInfo, report);
184	      });
185	    } catch (StorageContainerException ex) {
186	      // Preserve the specific result code (e.g. CONTAINER_ID_MISMATCH) for validation failures.
187	      metrics.incrementMerkleTreeDiffFailures();
188	      throw ex;
189	    } catch (IOException ex) {
190	      metrics.incrementMerkleTreeDiffFailures();
191	      throw new StorageContainerException("Container Diff failed for container " + containerID, ex,
192	          ContainerProtos.Result.IO_EXCEPTION);
193	    }
194	
195	    // Update the metrics based on the result of the diff.
196	    if (report.needsRepair()) {
197	      metrics.incrementRepairContainerDiffs();
198	    } else {
199	      metrics.incrementNoRepairContainerDiffs();
200	    }
201	
202	    return report;
203	  }
