205	  private void compareContainerMerkleTree(ContainerProtos.ContainerChecksumInfo thisChecksumInfo,
206	      ContainerProtos.ContainerChecksumInfo peerChecksumInfo, ContainerDiffReport report) {
207	    ContainerProtos.ContainerMerkleTree thisMerkleTree = thisChecksumInfo.getContainerMerkleTree();
208	    ContainerProtos.ContainerMerkleTree peerMerkleTree = peerChecksumInfo.getContainerMerkleTree();
209	    Set<Long> thisDeletedBlockSet = new HashSet<>(thisChecksumInfo.getDeletedBlocksList());
210	    Set<Long> peerDeletedBlockSet = new HashSet<>(peerChecksumInfo.getDeletedBlocksList());
211	    List<ContainerProtos.BlockMerkleTree> thisBlockMerkleTreeList = thisMerkleTree.getBlockMerkleTreeList();
212	    List<ContainerProtos.BlockMerkleTree> peerBlockMerkleTreeList = peerMerkleTree.getBlockMerkleTreeList();
213	    int thisIdx = 0;
214	    int peerIdx = 0;
215	
216	    // Step 1: Process both the block merkle tree list while elements are present in both the list.
217	    // The block merkle tree lists are sorted by block ID.
218	    while (thisIdx < thisBlockMerkleTreeList.size() && peerIdx < peerBlockMerkleTreeList.size()) {
219	      ContainerProtos.BlockMerkleTree thisBlockMerkleTree = thisBlockMerkleTreeList.get(thisIdx);
220	      ContainerProtos.BlockMerkleTree peerBlockMerkleTree = peerBlockMerkleTreeList.get(peerIdx);
221	
222	      // Skip the block if it is deleted in either our replica's or the peer's checksum info.
223	      if (isBlockDeleted(thisBlockMerkleTree.getBlockID(), thisDeletedBlockSet, peerDeletedBlockSet)) {
224	        thisIdx++;
225	        continue;
226	      }
227	      if (isBlockDeleted(peerBlockMerkleTree.getBlockID(), thisDeletedBlockSet, peerDeletedBlockSet)) {
228	        peerIdx++;
229	        continue;
230	      }
231	
232	      if (thisBlockMerkleTree.getBlockID() == peerBlockMerkleTree.getBlockID()) {
233	        // The block exists in both trees. Compare the block checksums, and if they differ, compare the chunks.
234	        if (thisBlockMerkleTree.getBlockChecksum() != peerBlockMerkleTree.getBlockChecksum()) {
235	          compareBlockMerkleTree(thisBlockMerkleTree, peerBlockMerkleTree, report);
236	        }
237	        thisIdx++;
238	        peerIdx++;
239	      } else if (thisBlockMerkleTree.getBlockID() < peerBlockMerkleTree.getBlockID()) {
240	        // Our replica has a block that the peer's replica does not. The peer is missing data, so exclude it.
241	        thisIdx++;
242	      } else {
243	        // The peer's replica has a block that our replica does not. This block is missing from our replica.
244	        report.addMissingBlock(peerBlockMerkleTree);
245	        peerIdx++;
246	      }
247	    }
248	
249	    // Step 2: Process the remaining blocks in the peer's block merkle tree list. These blocks are missing from our
250	    // replica. Blocks remaining only in our replica are ignored, since the peer is missing that data.
251	    while (peerIdx < peerBlockMerkleTreeList.size()) {
252	      ContainerProtos.BlockMerkleTree peerBlockMerkleTree = peerBlockMerkleTreeList.get(peerIdx);
253	      if (!isBlockDeleted(peerBlockMerkleTree.getBlockID(), thisDeletedBlockSet, peerDeletedBlockSet)) {
254	        report.addMissingBlock(peerBlockMerkleTree);
255	      }
256	      peerIdx++;
257	    }
258	  }
